    fn cli_takes_precedence_over_env() {
        let env = PartialConfig {
            host: Some("env.internal".to_string()),
            port: Some(9000),
            use_tls: Some(false),
        };
        let cli = PartialConfig {
            host: None,
            port: Some(7000),
            use_tls: Some(true),
        };

        let merged = merge_config(&defaults(), Some(&env), Some(&cli));

        assert_eq!(
            merged,
            Config {
                host: "env.internal".to_string(),
                port: 7000,
                use_tls: true,
            }
        );
    }
}

